namespace ghidra.app.plugin.core.compositeeditor;



using docking;
using docking.action;
using docking.action;
using ghidra.program.model.data;

/**
 * Action to apply a data type cycle group. For use in the composite data type editor.
 */
public class CycleGroupAction : CompositeEditorTableAction {

	private static string GROUP_NAME = DATA_ACTION_GROUP;
	private CycleGroup cycleGroup;

	public CycleGroupAction(CompositeEditorProvider<object,object> provider, CycleGroup cycleGroup) : base(provider, cycleGroup.getName())
    {

		setMenuBarData(
			new MenuData(new string[] { "Cycle", cycleGroup.getName() }, null, GROUP_NAME));
		setPopupMenuData(
			new MenuData(new string[] { "Cycle", cycleGroup.getName() }, null, GROUP_NAME));

		this.cycleGroup = cycleGroup;
		getPopupMenuData().setParentMenuGroup(GROUP_NAME);
		initKeyStroke(cycleGroup.getDefaultKeyStroke());
	}

	private void initKeyStroke(KeyStroke keyStroke) {
		if (keyStroke == null) {
			return;
		}

		setKeyBindingData(new KeyBindingData(keyStroke));
	}

	public CycleGroup getCycleGroup() {
		return cycleGroup;
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}
		model.cycleDataType(cycleGroup);
		requestTableFocus();
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return !hasIncompleteFieldEntry();
	}

	/* @Override */
	public string getHelpName() {
		return "Cycle";
	}
}
